﻿param(
    [string]$Godot = "godot"
)

$ErrorActionPreference = "Stop"
$clientRoot = Split-Path -Parent $PSScriptRoot
# ⚠️ **这是「离线门」** —— 里面**不许放要夹具的在线用例**。
#    2026-09-25 之前 `后端接入回归测试.gd` 混在这里，于是**夹具一停这扇门就死在它那儿**
#    （交接文档记成"夹具死怪、重启就好"——那是症状，根子是离线门不该依赖服务端）。
#    已把它挪回 `开发工具\跑在线用例.ps1`（那边本来就有它，叫「后端接入」）。
#    在线用例一律去那边跑 —— 那边每条都会起一个全新隔离夹具，且**不能并行**。
$testsBase64 = ""
$testsJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($testsBase64))
$tests = $testsJson | ConvertFrom-Json
$testResourceRoot = "res://" + [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("5rWL6K+V"))

foreach ($test in $tests) {
    & $Godot --headless --path $clientRoot --script "$testResourceRoot/$test"
    if ($LASTEXITCODE -ne 0) {
        throw "Regression failed: $test"
    }
}

$layoutAudit = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("56qX5Y+j5biD5bGA5L2T5qOALmdk"))
& $Godot --headless --path $clientRoot --script "$testResourceRoot/$layoutAudit"
if ($LASTEXITCODE -ne 0) {
    throw "Layout audit failed: $layoutAudit"
}

Write-Host "All $($tests.Count) regression suites and the window layout audit passed."
